/bin/zsh -lc "PYTHONDONTWRITEBYTECODE=1 python3 - <<'PY'
from fractions import Fraction
from ledger.splits import split_equal, split_percent

for n in range(1, 51):
    participants = [f'name-{i:02}' for i in range(n - 1, -1, -1)]
    for cents in range(1, 2 * n + 1):
        shares = split_equal(cents, participants)
        assert list(shares.values()) == sorted(shares.values(), reverse=True)
        assert list(shares) == sorted(participants)
        assert sum(shares.values()) == cents
        assert max(shares.values()) - min(shares.values()) <= 1

for weight in range(1, 10_000):
    balance = 10_000 - weight
    percents = {'bob': f'{weight // 100}.{weight % 100:02}', 'alice': f'{balance // 100}.{balance % 100:02}'}
    for cents in (1, 2, 3, 99, 10_001, 2**70 + 1):
        alice = Fraction(cents * balance, 10_000)
        bob = Fraction(cents * weight, 10_000)
        floors = {'alice': int(alice), 'bob': int(bob)}
        if sum(floors.values()) < cents:
            floors['alice' if alice % 1 >= bob % 1 else 'bob'] += 1
        assert split_percent(cents, percents) == floors
print('2,550 equal-split cases and 59,994 percentage cases matched the reference.')
PY"

