/bin/zsh -lc "PYTHONDONTWRITEBYTECODE=1 python3 - <<'PY'
import itertools
import json
import pathlib
import subprocess
import sys
import tempfile
import ledger

base = {'currency': 'USD', 'members': ['alice', 'bob'], 'expenses': []}
for field in base:
    invalid = base.copy()
    del invalid[field]
    for method in (ledger.balances, ledger.settle):
        try:
            method(invalid)
        except ledger.ValidationError:
            pass
        else:
            raise AssertionError(f'accepted missing {field"'!r}'"')
for ids in itertools.permutations(['', 'e', 'E', ' e ']):
    expenses = [
        {'id': expense_id, 'payer': 'alice', 'amount': '0.01', 'split': {'type': 'exact', 'amounts': {'bob': '0.01'}}}
        for expense_id in ids
    ]
    assert ledger.settle(dict(base, expenses=expenses)) == [('bob', 'alice', 4)]

with tempfile.TemporaryDirectory() as directory:
    path = pathlib.Path(directory) / 'group.json'
    cases = [
        ('Unicode case matching', json.dumps({
            'currency': 'USD', 'members': ['Straße', 'Bo'],
            'expenses': [{'id': 'road', 'payer': 'STRASSE', 'amount': '1', 'split': {'type': 'equal'}}],
        }), 0, 'bo: -0.50\\nstraße: +0.50\\n'),
        ('embedded newline', json.dumps(dict(base, members=['Anne\\nMarie'])), 0, 'anne\\nmarie: 0.00\\n'),
        ('repeated object key', '{\"currency\":\"USD\",\"members\":[\"alice\",\"bob\"],\"expenses\":[{\"id\":\"r\",\"payer\":\"alice\",\"amount\":\"1.00\",\"split\":{\"type\":\"exact\",\"amounts\":{\"bob\":\"99.00\",\"bob\":\"1.00\"}}}]}', 0, 'alice: +1.00\\nbob: -1.00\\n'),
        ('unused numeric value', '{\"currency\":\"USD\",\"members\":[\"alice\"],\"expenses\":[],\"extra\":1e99999999999999999999999999999}', 0, 'alice: 0.00\\n'),
    ]
    for label, raw, expected_code, expected_output in cases:
        path.write_text(raw, encoding='utf-8')
        result = subprocess.run([sys.executable, '-m', 'ledger', 'balances', str(path)], text=True, capture_output=True)
        assert (result.returncode, result.stdout, result.stderr) == (expected_code, expected_output, ''), (label, result)
        print(f'{label}: {result.stdout"'!r}'"')
print('Required fields reject omission; expense IDs preserve exact identity.')
PY"

